# Generated by manage.py generate_test_cases.
from typing import Any
from unittest.mock import patch

from django.contrib.contenttypes.models import ContentType
from django.core.exceptions import ValidationError
from django.core.management import call_command
from django.forms import modelform_factory
from django.http import HttpRequest
from django.test import RequestFactory, override_settings

from bloomerp.models.application_field import ApplicationField
from bloomerp.models.definition import BloomerpModelConfig, DataviewActionContext, FieldSettings, ObjectHTMLAction, ObjectModalAction
from bloomerp.templatetags.bloomerp import render_object_action
from bloomerp.tests.utils.users import create_admin
from bloomerp.tests.base import (
    BloomerpModelTestCase,
    ExpectedModelException,
    ModelScenario,
)


class TestApplicationFieldModel(BloomerpModelTestCase):
    model = ApplicationField

    def field_args(self) -> dict[str, Any]:
        """Build metadata for a genuine field without requiring a dynamic model."""
        return {
            "content_type": ContentType.objects.get_for_model(ContentType),
            "field": "app_label",
            "field_type": "CharField",
        }

    def valid_template_args(self) -> dict[str, Any]:
        """Provide a well-formed HTML/template override for lifecycle checks."""
        return {**self.field_args(), "advanced_rendering": "<b>{{ value }}</b>"}

    def invalid_template_args(self) -> dict[str, Any]:
        """Provide an unterminated conditional that must never be persisted."""
        return {**self.field_args(), "advanced_rendering": "{% if value %}"}

    def get_test_scenarios(self) -> list[ModelScenario[ApplicationField]]:
        """Cover optional overrides and syntax validation on both save phases."""
        return [
            ModelScenario(
                name="An override can be saved and cleared",
                create_args=self.valid_template_args,
                create_validators=lambda field: field.advanced_rendering == "<b>{{ value }}</b>",
                update_args={"advanced_rendering": ""},
                update_validators=lambda field: field.advanced_rendering == "",
            ),
            ModelScenario(
                name="New metadata has no override",
                create_args=self.field_args,
                create_validators=lambda field: field.advanced_rendering is None,
            ),
            ModelScenario(
                name="Malformed templates cannot be created",
                create_args=self.invalid_template_args,
                expected_exceptions=[ExpectedModelException(phase="create", exception=ValidationError)],
            ),
            ModelScenario(
                name="Malformed templates cannot replace saved overrides",
                create_args=self.valid_template_args,
                update_args={"advanced_rendering": "{% if value %}"},
                expected_exceptions=[ExpectedModelException(phase="update", exception=ValidationError)],
            ),
        ]

    def test_metadata_sync_preserves_rendering(self) -> None:
        """Refreshing framework metadata preserves the existing formatting choice."""
        field = ApplicationField.objects.create(**self.valid_template_args())
        call_command("save_application_fields", suppress_output=True)
        field.refresh_from_db()
        self.assertEqual(field.advanced_rendering, "<b>{{ value }}</b>")
        self.assertEqual(field.db_column, "app_label")

    def test_editing_exposes_only_rendering_and_validates_syntax(self) -> None:
        """Admin-style ModelForms omit static metadata and reject invalid templates."""
        form_class = modelform_factory(ApplicationField, fields="__all__")
        self.assertEqual(set(form_class.base_fields), {"advanced_rendering"})
        form = form_class(data={"advanced_rendering": "{% if value %}"})
        self.assertFalse(form.is_valid())
        self.assertIn("advanced_rendering", form.errors)
        layout = ApplicationField.bloomerp_config.detail_view_settings.get_default_layout()
        self.assertEqual([item.id for row in layout.rows for item in row.items], ["advanced_rendering"])

    def test_metadata_sync_applies_declared_rendering(self) -> None:
        """
        Use case: A model owns a field's rendering through its configuration.
        Expected result: Sync updates, clears, and validates the configured override.
        """
        # 1. Configure a real field alongside an existing manual override.
        field = ApplicationField.objects.create(**self.valid_template_args())
        config = BloomerpModelConfig(field_settings=[
            FieldSettings(field="app_label", advanced_rendering="<i>{{ value }}</i>"),
        ])
        with patch.object(ContentType, "bloomerp_config", config, create=True):
            # 2. Sync and verify the model's declaration wins over the stored override.
            call_command("save_application_fields", suppress_output=True)
            field.refresh_from_db()
            self.assertEqual(field.advanced_rendering, "<i>{{ value }}</i>")

            # 3. An explicit null clears the override on the next sync.
            config.field_settings[0].advanced_rendering = None
            call_command("save_application_fields", suppress_output=True)
            field.refresh_from_db()
            self.assertIsNone(field.advanced_rendering)

            # 4. Invalid declarations cannot replace persisted rendering.
            config.field_settings[0].advanced_rendering = "{% if value %}"
            call_command("save_application_fields", suppress_output=True)
            field.refresh_from_db()
            self.assertIsNone(field.advanced_rendering)

    def object_html_context(self, context: DataviewActionContext) -> dict[str, str]:
        """Use the object action's shared context to produce custom template data."""
        self.assertEqual(context.selected_ids, [str(self.html_field.pk)])
        self.assertEqual(list(context.queryset), [self.html_field])
        self.assertEqual(context.model, ApplicationField)
        self.assertIsNone(context.preference)
        return {"custom_text": "Configured object context"}

    @staticmethod
    def object_modal_endpoint(obj: ApplicationField) -> str:
        """Return a stable modal URL for an application-field action."""
        return "/review/"

    def test_object_action_rendering_uses_custom_context_and_modal_fallback(self) -> None:
        """
        Use case: A detail page renders configured HTML and modal actions.
        Expected result: Custom context augments existing variables and labels supply titles.
        """
        # 1. Prepare a persisted object, authorized request and a minimal template.
        self.html_field = ApplicationField.objects.create(**self.field_args())
        request: HttpRequest = RequestFactory().get("/")
        request.user = create_admin()
        templates = [{
            "BACKEND": "django.template.backends.django.DjangoTemplates",
            "OPTIONS": {"loaders": [("django.template.loaders.locmem.Loader", {
                "action.html": "{{ custom_text }}: {{ object.field }}",
            })]},
        }]
        # 2. The nullable callback preserves old HTML behavior and can supply new data.
        with override_settings(TEMPLATES=templates):
            plain = ObjectHTMLAction(template_name="action.html")
            self.assertEqual(render_object_action(plain, self.html_field, request), ": app_label")
            action = ObjectHTMLAction(template_name="action.html", context_func=self.object_html_context)
            self.assertEqual(render_object_action(action, self.html_field, request), "Configured object context: app_label")
        # 3. The actual modal button receives the label as its default title.
        modal = ObjectModalAction(id="review", label="Review field", endpoint=self.object_modal_endpoint)
        html = render_object_action(modal, self.html_field, request)
        self.assertIn('bloomerp-set-modal-title-to="Review field"', html)
